import json


def save_todos(todos: list[dict[str, object]], path: str) -> None:
    """Write the todo list to a JSON file."""
    with open(path, "w") as f:
        json.dump(todos, f, indent=2)


def load_todos(path: str) -> list[dict[str, object]]:
    """Read a todo list from a JSON file."""
    with open(path) as f:
        return json.load(f)

