import pytest

from calc import divide, percent


def test_divide_basic():
    assert divide(10, 4) == 2.5


def test_divide_negative():
    assert divide(-6, 3) == -2


def test_divide_by_zero_raises():
    with pytest.raises(ValueError, match="cannot divide by zero"):
        divide(1, 0)


def test_percent_basic():
    assert percent(25, 100) == 25


def test_percent_fraction():
    assert percent(1, 3) == pytest.approx(33.333, rel=1e-3)


def test_percent_zero_whole_raises():
    with pytest.raises(ValueError, match="cannot divide by zero"):
        percent(50, 0)

import pytest

from metrics import mean


def test_mean_basic():
    assert mean([1, 2, 3]) == 2


def test_mean_single_value():
    assert mean([7]) == 7


def test_mean_floats():
    assert mean([1.5, 2.5]) == 2.0


def test_mean_negative_values():
    assert mean([-2, 2]) == 0


def test_mean_empty_raises():
    with pytest.raises(ValueError, match="no values"):
        mean([])

